oxy_webhelp_navlinks = {"db2_purescale-d39307e34257":{"topics":[{"title":"Discovery of Db2 pureScale","shortdesc":"<p class=\"shortdesc\">Db2 pureScale discovery involves identifying components within a pureScale cluster,         such as member hosts and pureScale instances. You can discover and protect your pureScale         instances and their associated databases within Db2 using <span class=\"ph\">RSC<\/span> for improved         management and protection.<\/p>","href":"db2\/discovery_db2_purescale.html","attributes":{"data-id":"discovery_db2_purescale"},"menu":{"hasChildren":false},"tocID":"discovery_db2_purescale-d39307e34268","topics":[]},{"title":"Topology changes within a pureScale cluster","shortdesc":"<p class=\"shortdesc\">Topology changes within a pureScale cluster, such as adding or dropping members,         optimize performance and resource utilization across the database system.<\/p>","href":"db2\/topology_changes_purescale_cluster.html","attributes":{"data-id":"topology_changes_purescale_cluster"},"menu":{"hasChildren":false},"tocID":"topology_changes_purescale_cluster-d39307e34282","topics":[]}]}};